fn runtime_filter_runtime_dependencies_are_allowed(source_rel: &str, text: &str) -> bool {
    let Some(allowed_prefixes) = runtime_filter_runtime_dependency_allowlist(source_rel) else {
        return false;
    };
    let local_roots = runtime_filter_runtime_local_roots(text);
    let canonical_allowed = rust_production_canonical_paths(text, source_rel)
        .into_iter()
        .map(|canonical| runtime_filter_dependency_path(&canonical, source_rel))
        .filter(|canonical| {
            !canonical
                .first()
                .is_some_and(|root| local_roots.contains(root))
                && !runtime_filter_path_is_rust_prelude(canonical)
        })
        .all(|canonical| {
            runtime_filter_task4_exact_path_ledger(source_rel, &canonical).unwrap_or_else(|| {
                runtime_filter_path_is_allowlisted(&canonical, &allowed_prefixes)
            })
        });
    canonical_allowed
        && runtime_filter_runtime_extern_crates(text)
            .into_iter()
            .all(|path| {
                runtime_filter_task4_exact_path_ledger(source_rel, &path)
                    .unwrap_or_else(|| runtime_filter_path_is_allowlisted(&path, &allowed_prefixes))
            })
        && runtime_filter_task4_bare_path_inventory(source_rel).is_none_or(|_| {
            runtime_filter_task4_bare_paths(text).is_ok_and(|actual| {
                runtime_filter_task4_bare_path_inventory_violations(source_rel, &actual).is_empty()
            })
        })
}

fn runtime_filter_transport_public_alias_violations(source_rel: &str, text: &str) -> Vec<String> {
    #[derive(Clone)]
    struct TypeAliasDeclaration {
        name: String,
        scope: Vec<String>,
        expands_visibility: bool,
        targets: Vec<Vec<String>>,
    }

    #[derive(Default)]
    struct TypePathAudit {
        paths: Vec<Vec<String>>,
    }
    impl<'ast> syn::visit::Visit<'ast> for TypePathAudit {
        fn visit_type_path(&mut self, path: &'ast syn::TypePath) {
            if path.qself.is_none() {
                self.paths.push(
                    path.path
                        .segments
                        .iter()
                        .map(|segment| segment.ident.to_string())
                        .collect(),
                );
            }
            syn::visit::visit_type_path(self, path);
        }
    }

    fn collect_aliases(
        items: &[syn::Item],
        scope: &mut Vec<String>,
        declarations: &mut Vec<TypeAliasDeclaration>,
    ) {
        for item in items {
            if nfe_4_syn_attrs_require_test(nfe_4_syn_item_attrs(item)) {
                continue;
            }
            match item {
                syn::Item::Type(alias) => {
                    let mut audit = TypePathAudit::default();
                    syn::visit::Visit::visit_type(&mut audit, &alias.ty);
                    let expands_visibility = match &alias.vis {
                        syn::Visibility::Inherited => false,
                        syn::Visibility::Public(_) => true,
                        syn::Visibility::Restricted(restricted) => {
                            !restricted.path.is_ident("self")
                        }
                    };
                    declarations.push(TypeAliasDeclaration {
                        name: alias.ident.to_string(),
                        scope: scope.clone(),
                        expands_visibility,
                        targets: audit.paths,
                    });
                }
                syn::Item::Mod(module) => {
                    let Some((_, items)) = &module.content else {
                        continue;
                    };
                    scope.push(module.ident.to_string());
                    collect_aliases(items, scope, declarations);
                    scope.pop();
                }
                _ => {}
            }
        }
    }

    let production = rust_sanitized_production_text(text);
    let file = match syn::parse_file(&production).or_else(|_| syn::parse_file(text)) {
        Ok(file) => file,
        Err(error) => {
            return vec![format!(
                "{source_rel}: native runtime-filter transport alias surface must parse: {error}"
            )];
        }
    };
    let mut declarations = Vec::new();
    collect_aliases(&file.items, &mut Vec::new(), &mut declarations);

    let mut aliases = rust_production_scoped_aliases(text);
    for declaration in &declarations {
        let entry = aliases
            .entry((declaration.scope.clone(), declaration.name.clone()))
            .or_default();
        for target in &declaration.targets {
            let candidate = RustScopedUsePath {
                segments: target.clone(),
                inline_modules: declaration.scope.clone(),
            };
            if !entry.contains(&candidate) {
                entry.push(candidate);
            }
        }
    }

    let transport_prefix = ["crate", "runtime_filter", "port", "transport"];
    declarations
        .into_iter()
        .filter(|declaration| declaration.expands_visibility)
        .filter_map(|declaration| {
            let exposes_transport = declaration.targets.iter().any(|target| {
                let resolved = rust_resolve_scoped_paths(
                    target,
                    &declaration.scope,
                    &aliases,
                    &mut BTreeSet::new(),
                    0,
                )
                .unwrap_or_else(|| {
                    vec![RustScopedUsePath {
                        segments: target.clone(),
                        inline_modules: declaration.scope.clone(),
                    }]
                });
                resolved.into_iter().any(|resolved| {
                    rust_canonical_path_segments_in_scope(
                        &resolved.segments,
                        source_rel,
                        &resolved.inline_modules,
                    )
                    .is_some_and(|canonical| {
                        canonical.len() >= transport_prefix.len()
                            && canonical
                                .iter()
                                .zip(transport_prefix)
                                .all(|(actual, expected)| actual == expected)
                    })
                })
            });
            exposes_transport.then(|| {
                format!(
                    "{source_rel}: native runtime-filter transport owner must not expose transport type alias {}",
                    declaration.name
                )
            })
        })
        .collect()
}

fn runtime_filter_transport_use_expands_visibility(import: &str) -> bool {
    !matches!(
        rust_use_visibility(import),
        "private" | "pub(self)" | "pub(inself)"
    )
}

fn runtime_filter_transport_extern_self_alias_violations(
    source_rel: &str,
    text: &str,
) -> Vec<String> {
    #[derive(Default)]
    struct ExternSelfAudit {
        aliases: Vec<String>,
    }
    impl<'ast> syn::visit::Visit<'ast> for ExternSelfAudit {
        fn visit_item(&mut self, item: &'ast syn::Item) {
            if nfe_4_syn_attrs_require_test(nfe_4_syn_item_attrs(item)) {
                return;
            }
            syn::visit::visit_item(self, item);
        }

        fn visit_stmt(&mut self, statement: &'ast syn::Stmt) {
            if nfe_4_syn_attrs_require_test(nfe_4_syn_stmt_attrs(statement)) {
                return;
            }
            syn::visit::visit_stmt(self, statement);
        }

        fn visit_expr(&mut self, expression: &'ast syn::Expr) {
            if nfe_4_syn_attrs_require_test(nfe_4_syn_expr_attrs(expression)) {
                return;
            }
            syn::visit::visit_expr(self, expression);
        }

        fn visit_item_extern_crate(&mut self, extern_crate: &'ast syn::ItemExternCrate) {
            if extern_crate.ident.to_string() == "self" {
                self.aliases.push(
                    extern_crate
                        .rename
                        .as_ref()
                        .map_or_else(|| "self".to_string(), |(_, alias)| alias.to_string()),
                );
            }
        }
    }

    let Ok(file) = syn::parse_file(text) else {
        return Vec::new();
    };
    let mut audit = ExternSelfAudit::default();
    syn::visit::Visit::visit_file(&mut audit, &file);
    audit
        .aliases
        .into_iter()
        .map(|alias| {
            format!(
                "{source_rel}: native runtime-filter transport owner must not declare production crate-root alias {alias}"
            )
        })
        .collect()
}

fn runtime_filter_transport_ingress_boundary_violations(
    source_rel: &str,
    text: &str,
) -> Vec<String> {
    const ADAPTER: &str = "src/service/grpc_runtime_filter_adapter.rs";
    const SERVICE_INJECTION_OWNER: &str = "src/service/grpc_server.rs";
    const TRANSPORT_OWNER: &str = "src/runtime_filter/port/transport.rs";

    if source_rel == TRANSPORT_OWNER {
        return Vec::new();
    }

    let canonical = rust_production_canonical_paths(text, source_rel);
    let transport_prefix = [
        "crate".to_string(),
        "runtime_filter".to_string(),
        "port".to_string(),
        "transport".to_string(),
    ];
    let transport_paths = canonical
        .iter()
        .filter(|path| path.starts_with(&transport_prefix))
        .collect::<Vec<_>>();

    let mut export_violations = Vec::new();
    if matches!(source_rel, ADAPTER | SERVICE_INJECTION_OWNER) {
        export_violations.extend(runtime_filter_transport_extern_self_alias_violations(
            source_rel, text,
        ));
        export_violations.extend(
            rust_production_scoped_use_statements(text)
                .into_iter()
                .filter(|import| {
                    runtime_filter_transport_use_expands_visibility(&import.import)
                })
                .filter(|import| {
                    rust_canonical_use_segments_in_scope(
                        &import.import,
                        source_rel,
                        &import.inline_modules,
                    )
                    .is_some_and(|canonical| {
                        runtime_filter_path_is_allowlisted(
                            &canonical,
                            &[&["crate", "runtime_filter", "port", "transport"]],
                        )
                    })
                })
                .map(|import| {
                    format!(
                        "{source_rel}: native runtime-filter transport surface must not be re-exported from inline scope {}: {}",
                        import.inline_modules.join("::"),
                        import.import
                    )
                }),
        );

        export_violations.extend(runtime_filter_transport_public_alias_violations(
            source_rel, text,
        ));
    }

    if source_rel == ADAPTER {
        let forbidden_prefixes: &[&[&str]] = &[
            &["crate", "runtime_filter", "core"],
            &["crate", "runtime_filter", "router"],
            &["crate", "runtime_filter", "service"],
            &["crate", "runtime", "query_context"],
            &["crate", "runtime", "runtime_filter_hub"],
            &["crate", "runtime", "runtime_filter_worker"],
            &["crate", "exec", "operators"],
            &["crate", "lower"],
            &["crate", "sql", "planner"],
            &["crate", "service", "grpc_client"],
            &["crate", "service", "exchange_sender"],
        ];
        export_violations.extend(
            canonical
                .iter()
                .filter(|path| {
                    forbidden_prefixes.iter().any(|prefix| {
                        path.iter()
                            .map(String::as_str)
                            .zip(prefix.iter().copied())
                            .all(|(actual, expected)| actual == expected)
                            && path.len() >= prefix.len()
                    })
                })
                .map(|path| {
                    format!(
                        "{source_rel}: native runtime-filter ingress adapter cannot own {}",
                        path.join("::")
                    )
                })
                .collect::<Vec<_>>(),
        );
        return export_violations;
    }

    if source_rel == SERVICE_INJECTION_OWNER {
        export_violations.extend(transport_paths
            .into_iter()
            .filter(|path| {
                path.as_slice()
                    != [
                        "crate",
                        "runtime_filter",
                        "port",
                        "transport",
                        "RuntimeFilterEnvelopeIngress",
                    ]
            })
            .map(|path| {
                format!(
                    "{source_rel}: GrpcService may inject only the ingress trait, not consume {}",
                    path.join("::")
                )
            })
            .collect::<Vec<_>>());
        let allowed_adapter_paths: &[&[&str]] = &[
            &[
                "crate",
                "service",
                "grpc_runtime_filter_adapter",
                "default_runtime_filter_envelope_ingress",
            ],
            &[
                "crate",
                "service",
                "grpc_runtime_filter_adapter",
                "handle_runtime_filter_envelope",
            ],
        ];
        export_violations.extend(
            canonical
                .iter()
                .filter(|path| {
                    path.starts_with(&[
                        "crate".to_string(),
                        "service".to_string(),
                        "grpc_runtime_filter_adapter".to_string(),
                    ]) && !runtime_filter_path_is_exactly_allowlisted(path, allowed_adapter_paths)
                })
                .map(|path| {
                    format!(
                        "{source_rel}: GrpcService may consume only the two named adapter functions: {}",
                        path.join("::")
                    )
                }),
        );
        return export_violations;
    }

    let adapter_prefix = [
        "crate".to_string(),
        "service".to_string(),
        "grpc_runtime_filter_adapter".to_string(),
    ];
    export_violations.extend(transport_paths
        .into_iter()
        .map(|path| {
            format!(
                "{source_rel}: runtime-filter transport ingress is owned by the named gRPC adapter: {}",
                path.join("::")
            )
        })
        .collect::<Vec<_>>());
    export_violations.extend(
        canonical
            .iter()
            .filter(|path| path.starts_with(&adapter_prefix))
            .map(|path| {
                format!(
                    "{source_rel}: runtime-filter transport adapter surface is private to GrpcService: {}",
                    path.join("::")
                )
            }),
    );
    export_violations
}

fn runtime_filter_runtime_boundary_violations(source_rel: &str, text: &str) -> Vec<String> {
    if !source_rel.starts_with("src/runtime_filter/") {
        let production = rust_sanitized_production_text(text);
        let canonical = rust_production_canonical_paths(text, source_rel);
        let references_service = production.contains("RuntimeFilterService")
            || production.contains("runtime_filter_service")
            || canonical.iter().any(|path| {
                path.starts_with(&[
                    "crate".to_string(),
                    "runtime_filter".to_string(),
                    "service".to_string(),
                ])
            });
        let references_data_plane_port = [
            "RuntimeFilterInstallView",
            "CompleteOnceChannelDeployment",
            "ProducerAdapter",
            "BlockingSnapshotSubscription",
            "ValueDomainDelta",
            "LogicalSnapshot",
        ]
        .into_iter()
        .any(|owner| {
            if owner != "ValueDomainDelta" {
                return production.contains(owner);
            }
            canonical.iter().any(|path| {
                path.last().is_some_and(|segment| segment == owner)
                    && !runtime_filter_path_is_exactly_allowlisted(
                        path,
                        &[&[
                            "crate",
                            "runtime_filter",
                            "model",
                            "contract",
                            "ContributionKind",
                            "ValueDomainDelta",
                        ]],
                    )
            })
        });
        let references_concrete_event_sink = production.contains("RegistryRuntimeFilterEventSink")
            || canonical.iter().any(|path| {
                path.last()
                    .is_some_and(|name| name == "RegistryRuntimeFilterEventSink")
            });
        let production_tokens = rust_use_tokens(&production);
        let references_event_port = production_tokens.iter().any(|token| {
            matches!(
                token.as_str(),
                "RuntimeFilterEventSink" | "RuntimeFilterEvent"
            )
        }) || canonical.iter().any(|path| {
            path.starts_with(&[
                "crate".to_string(),
                "runtime_filter".to_string(),
                "port".to_string(),
                "events".to_string(),
            ])
        });
        let allowed_owner = matches!(
            source_rel,
            "src/runtime/query_context.rs" | "src/runtime/runtime_filter_observability.rs"
        );
        let references_runtime_surface = references_service
            || references_data_plane_port
            || references_event_port
            || references_concrete_event_sink;
        let calls_data_plane = production_tokens.windows(3).any(|window| {
            matches!(window[0].as_str(), "." | "::")
                && matches!(
                    window[1].as_str(),
                    "install" | "open_producer" | "open_subscription" | "subscribe"
                )
                && window[2] == "("
        });
        let export_surface_violations = (source_rel == "src/runtime/query_context.rs")
            .then(|| runtime_filter_query_context_export_surface_violations(text))
            .unwrap_or_default();
        let allowed_reference = match source_rel {
            "src/runtime/query_context.rs" => {
                (references_service || references_concrete_event_sink)
                    && !references_data_plane_port
                    && !references_event_port
                    && !calls_data_plane
            }
            "src/runtime/runtime_filter_observability.rs" => {
                !references_service && !references_data_plane_port && !calls_data_plane
            }
            _ => false,
        };
        let mut violations = ((references_runtime_surface
            && (!allowed_owner || !allowed_reference))
            || (source_rel == "src/runtime/query_context.rs" && calls_data_plane)
            || !export_surface_violations.is_empty())
        .then(|| format!("{source_rel}: runtime-filter Service is harness-only before RFD-6"))
        .into_iter()
        .collect::<Vec<_>>();
        violations.extend(runtime_filter_transport_ingress_boundary_violations(
            source_rel, text,
        ));
        return violations;
    }

    let Some(allowed_prefixes) = runtime_filter_runtime_dependency_allowlist(source_rel) else {
        return vec![format!(
            "{source_rel}: unrecognized runtime-filter Core/Port/Router/Service source"
        )];
    };
    let local_roots = runtime_filter_runtime_local_roots(text);
    let canonical_dependencies = rust_production_canonical_paths(text, source_rel)
        .into_iter()
        .map(|canonical| runtime_filter_dependency_path(&canonical, source_rel))
        .filter(|canonical| {
            !canonical
                .first()
                .is_some_and(|root| local_roots.contains(root))
                && !runtime_filter_path_is_rust_prelude(canonical)
        })
        .collect::<BTreeSet<_>>();
    let external_dependencies = runtime_filter_runtime_extern_crates(text);
    let mut violations = canonical_dependencies
        .iter()
        .filter(|canonical| {
            !runtime_filter_task4_exact_path_ledger(source_rel, canonical)
                .unwrap_or_else(|| runtime_filter_path_is_allowlisted(canonical, &allowed_prefixes))
        })
        .map(|canonical| format!("{source_rel}: {}", canonical.join("::")))
        .collect::<BTreeSet<_>>();
    violations.extend(
        external_dependencies
            .iter()
            .filter(|path| {
                !runtime_filter_task4_exact_path_ledger(source_rel, path)
                    .unwrap_or_else(|| runtime_filter_path_is_allowlisted(path, &allowed_prefixes))
            })
            .map(|path| format!("{source_rel}: external {}", path.join("::"))),
    );
    if let Some(exact_inventory) = runtime_filter_task4_whole_exact_inventory(source_rel)
        .or_else(|| runtime_filter_task4_added_exact_inventory(source_rel))
    {
        let expected = exact_inventory
            .lines()
            .map(str::trim)
            .filter(|path| !path.is_empty())
            .map(str::to_string)
            .collect::<BTreeSet<_>>();
        let actual = canonical_dependencies
            .iter()
            .chain(external_dependencies.iter())
            .map(|path| path.join("::"))
            .collect::<BTreeSet<_>>();
        violations.extend(
            expected
                .difference(&actual)
                .map(|path| format!("{source_rel}: stale exact dependency {path}")),
        );
    }
    if runtime_filter_task4_bare_path_inventory(source_rel).is_some() {
        match runtime_filter_task4_bare_paths(text) {
            Ok(actual) => violations.extend(runtime_filter_task4_bare_path_inventory_violations(
                source_rel, &actual,
            )),
            Err(error) => {
                violations.insert(format!(
                    "{source_rel}: whole-exact bare path source must parse: {error}"
                ));
            }
        }
    }
    let production_tokens = rust_use_tokens(&rust_sanitized_production_text(text));
    let production_source_tokens = rust_source_tokens(&rust_sanitized_production_text(text));
    let has_path_attribute = production_source_tokens
        .iter()
        .enumerate()
        .any(|(index, token)| {
            if token.text != "#" {
                return false;
            }
            let open = if production_source_tokens
                .get(index + 1)
                .is_some_and(|token| token.text == "[")
            {
                index + 1
            } else if production_source_tokens
                .get(index + 1)
                .is_some_and(|token| token.text == "!")
                && production_source_tokens
                    .get(index + 2)
                    .is_some_and(|token| token.text == "[")
            {
                index + 2
            } else {
                return false;
            };
            rust_matching_token(&production_source_tokens, open, "[", "]").is_some_and(|close| {
                production_source_tokens[open + 1..close]
                    .windows(2)
                    .any(|window| window[0].text == "path" && window[1].text == "=")
            })
        });
    if has_path_attribute {
        violations.insert(format!(
            "{source_rel}: #[path] source indirection is forbidden in runtime-filter namespaces"
        ));
    }
    if production_tokens.windows(3).any(|window| {
        window[0] == "include" && window[1] == "!" && matches!(window[2].as_str(), "(" | "[" | "{")
    }) {
        violations.insert(format!(
            "{source_rel}: include! source indirection is forbidden in runtime-filter namespaces"
        ));
    }
    violations.extend(runtime_filter_global_registry_violations(source_rel, text));
    violations.extend(runtime_filter_materializer_semantic_violations(
        source_rel, text,
    ));
    violations.extend(runtime_filter_transport_ingress_boundary_violations(
        source_rel, text,
    ));
    if matches!(
        source_rel,
        "src/runtime_filter/core/mod.rs"
            | "src/runtime_filter/materializer/mod.rs"
            | "src/runtime_filter/port/mod.rs"
            | "src/runtime_filter/router/mod.rs"
            | "src/runtime_filter/service/mod.rs"
    ) {
        violations.extend(runtime_filter_inner_dead_code_violations(source_rel, text));
    }
    violations.into_iter().collect()
}

