#[test]
fn runtime_filter_query_context_lock_detector_rejects_shutdown_under_manager_lock() {
    const GOOD: &str = r#"
impl QueryContextManager {
fn abort_query() {
    let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };
    if let Some(service) = service { service.cancel(); }
}
fn cancel_query() {
    let (service, finsts, completions) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts, completions) };
    if let Some(service) = service { service.cancel(); }
}
fn clean_expired() {
    let expired = { let guard = self.inner.lock(); let expired = collect(&guard); expired };
    for (qid, ctx) in expired { ctx.runtime_filter_service().shutdown(); drop(ctx); }
}
fn finish_fragment_internal() {
    let mut guard = self.inner.lock();
    let Some(mut ctx) = guard.active.remove() else { return; };
    if ctx.is_dead() { drop(guard); ctx.runtime_filter_service().shutdown(); drop(ctx); }
}
}
"#;
    let good_violations = runtime_filter_query_context_lock_discipline_violations(GOOD);
    assert!(
        good_violations.is_empty(),
        "GOOD lock fixture must pass:\n{}",
        good_violations.join("\n")
    );

    for bad in [
        GOOD.replace(
            "(service, finsts) };\n    if let Some(service) = service { service.cancel(); }",
            "service.cancel(); (service, finsts) };",
        ),
        GOOD.replace(
            "expired };\n    for (qid, ctx) in expired { ctx.runtime_filter_service().shutdown(); drop(ctx); }",
            "ctx.runtime_filter_service().shutdown(); expired };",
        ),
        GOOD.replace(
            "drop(guard); ctx.runtime_filter_service().shutdown(); drop(ctx);",
            "ctx.runtime_filter_service().shutdown(); drop(guard); drop(ctx);",
        ),
    ] {
        assert!(
            !runtime_filter_query_context_lock_discipline_violations(&bad).is_empty(),
            "lock-discipline detector must reject shutdown/cancel before manager-lock release"
        );
    }
}

#[test]
fn runtime_filter_query_context_lock_detector_rejects_decoys_escape_and_relock() {
    const GOOD: &str = r#"
impl QueryContextManager {
    fn abort_query() {
        let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };
        if let Some(service) = service { service.cancel(); }
    }
    fn cancel_query() {
        let (service, finsts, completions) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts, completions) };
        if let Some(service) = service { service.cancel(); }
    }
    fn clean_expired() {
        let expired = { let guard = self.inner.lock(); let expired = collect(&guard); expired };
        for (qid, ctx) in expired { ctx.runtime_filter_service().shutdown(); drop(ctx); }
    }
    fn finish_fragment_internal() {
        let mut guard = self.inner.lock();
        let Some(mut ctx) = guard.active.remove() else { return; };
        if ctx.is_dead() { drop(guard); ctx.runtime_filter_service().shutdown(); drop(ctx); }
    }
}
"#;
    let good_violations = runtime_filter_query_context_lock_discipline_violations(GOOD);
    assert!(
        good_violations.is_empty(),
        "GOOD lock fixture must pass:\n{}",
        good_violations.join("\n")
    );
    let unrelated = GOOD.replace(
        "(service, finsts) };",
        "other.clone(); drop(other); (service, finsts) };",
    );
    assert!(
        runtime_filter_query_context_lock_discipline_violations(&unrelated).is_empty(),
        "unrelated cancel/drop calls are outside the runtime-filter lifecycle contract"
    );

    let bad_sources = [
        GOOD.replace(
            "if let Some(service) = service { service.cancel(); }",
            "if false { service.cancel(); }",
        ),
        GOOD.replacen(
            "let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };\n        if let Some(service) = service { service.cancel(); }",
            "let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };\n        self.inner.lock().unwrap().runtime_filter_service().cancel();",
            1,
        ),
        GOOD.replace(
            "(service, finsts) };",
            "service.cancel(); (service, finsts) };",
        ),
        GOOD.replace("expired };", "events.record(event); expired };"),
        GOOD.replace("expired };", "drop(ctx); expired };"),
        GOOD.replace("expired };", "(&guard, expired) };"),
        GOOD.replace("expired };", "GuardBox { guard } };"),
        GOOD.replace("expired };", "[Some(GuardBox { guard })] };"),
        GOOD.replace("expired };", "(|| GuardBox { guard }) };"),
        GOOD.replace(
            "(service, finsts) };",
            "let svc = ctx.runtime_filter_service(); svc.cancel(); (service, finsts) };",
        ),
        GOOD.replace(
            "(service, finsts) };",
            "let svc = Arc::clone(&service); svc.cancel(); (service, finsts) };",
        ),
        GOOD.replace(
            "let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };",
            "let (service, finsts) = { if false { let guard = self.inner.lock(); drop(guard); } let service = make_service(); (service, finsts) };",
        ),
        GOOD.replace(
            "let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };",
            "let (service, finsts) = (service, finsts); if false { let guard = self.inner.lock(); drop(guard); }",
        ),
        GOOD.replace(
            "let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };",
            "let acquire = || { let guard = self.inner.lock(); drop(guard); }; let (service, finsts) = (service, finsts);",
        ),
        GOOD.replace(
            "let (service, finsts) = { let guard = self.inner.lock(); let service = guard.context().runtime_filter_service(); (service, finsts) };",
            "let (service, finsts) = { manager_access!(); (service, finsts) };",
        ),
        GOOD.replace(
            "drop(guard); ctx.runtime_filter_service().shutdown();",
            "if false { drop(guard); } ctx.runtime_filter_service().shutdown();",
        ),
        GOOD.replace(
            "drop(guard); ctx.runtime_filter_service().shutdown();",
            "drop(guard); let guard = self.inner.lock(); ctx.runtime_filter_service().shutdown();",
        ),
        format!(
            "fn abort_query() {{ service.cancel(); }}\n{}",
            GOOD.replace(
                "(service, finsts) };",
                "service.cancel(); (service, finsts) };",
            )
        ),
    ];
    for bad in bad_sources {
        assert!(
            !runtime_filter_query_context_lock_discipline_violations(&bad).is_empty(),
            "lock detector must reject manager-lock decoy/escape/relock:\n{bad}"
        );
    }
}

#[test]
fn runtime_filter_action_dispatch_detector_requires_returned_channel_action() {
    let good = r#"
fn finish(&self, action: crate::runtime_filter::core::channel::ChannelAction) {
    self.dispatcher.dispatch(self.channel_id, action);
}
fn submit(&self) { self.channel.submit().map(|action| self.finish(action)); }
fn close_partition(&self) { self.channel.close_partition().map(|action| self.finish(action)); }
fn fail(&self) { self.channel.fail_instance().map(|action| self.finish(action)); }
"#;
    assert!(runtime_filter_action_dispatch_boundary_violations(good).is_empty());
    let try_wrapped = good.replace(
        "self.dispatcher.dispatch(self.channel_id, action);",
        "self.dispatcher.dispatch(self.channel_id, action)?;",
    );
    assert!(
        runtime_filter_action_dispatch_boundary_violations(&try_wrapped).is_empty(),
        "finish may use a top-level try wrapper around the exact dispatch"
    );
    let cfg_test_only_impl_finish = r#"
macro_rules! finish_token_decoy {
    () => {
        fn finish(&self, action: crate::runtime_filter::core::channel::ChannelAction) {
            self.dispatcher.dispatch(self.channel_id, action);
        }
    };
}
struct Producer;
impl Producer {
    #[cfg(test)]
    fn finish(&self, action: crate::runtime_filter::core::channel::ChannelAction) {
        self.dispatcher.dispatch(self.channel_id, action);
    }
}
fn submit(&self) { self.channel.submit().map(|action| self.finish(action)); }
fn close_partition(&self) { self.channel.close_partition().map(|action| self.finish(action)); }
fn fail(&self) { self.channel.fail_instance().map(|action| self.finish(action)); }
fn force_sanitizer_failure() {
    let _value = 1 + #[cfg(test)] 2;
}
"#;
    assert!(
        !runtime_filter_action_dispatch_boundary_violations(cfg_test_only_impl_finish).is_empty(),
        "a cfg(test)-only impl finish must not satisfy the raw action fallback"
    );
    let cfg_test_only_body_dispatch = r#"
macro_rules! finish_token_decoy {
    () => {
        fn finish(&self, action: crate::runtime_filter::core::channel::ChannelAction) {
            self.dispatcher.dispatch(self.channel_id, action);
        }
    };
}
fn finish(&self, action: crate::runtime_filter::core::channel::ChannelAction) {
    #[cfg(test)]
    self.dispatcher.dispatch(self.channel_id, action);
}
fn submit(&self) { self.channel.submit().map(|action| self.finish(action)); }
fn close_partition(&self) { self.channel.close_partition().map(|action| self.finish(action)); }
fn fail(&self) { self.channel.fail_instance().map(|action| self.finish(action)); }
fn force_sanitizer_failure() {
    let _value = 1 + #[cfg(test)] 2;
}
"#;
    assert!(
        !runtime_filter_action_dispatch_boundary_violations(cfg_test_only_body_dispatch).is_empty(),
        "a cfg(test)-only finish body dispatch must not satisfy the raw action fallback"
    );
    let nested_cfg_test_only_body_dispatch = cfg_test_only_body_dispatch.replace(
        "    #[cfg(test)]\n    self.dispatcher.dispatch(self.channel_id, action);",
        "    {\n        #[cfg(test)]\n        self.dispatcher.dispatch(self.channel_id, action);\n    }",
    );
    assert!(
        !runtime_filter_action_dispatch_boundary_violations(&nested_cfg_test_only_body_dispatch)
            .is_empty(),
        "a nested cfg(test)-only finish body dispatch must not satisfy the raw action fallback"
    );
    let tautologies = (0..12)
        .map(|index| format!("any(feature = \"x{index}\", not(feature = \"x{index}\"))"))
        .collect::<Vec<_>>()
        .join(", ");
    let hard_unsatisfiable =
        format!("#[cfg(all({tautologies}, feature = \"zz\", not(feature = \"zz\")))]");
    let unproven_body_dispatch = format!(
        r#"
fn finish(&self, action: crate::runtime_filter::core::channel::ChannelAction) {{
    {hard_unsatisfiable}
    self.dispatcher.dispatch(self.channel_id, action);
}}
fn submit(&self) {{ self.channel.submit().map(|action| self.finish(action)); }}
fn close_partition(&self) {{ self.channel.close_partition().map(|action| self.finish(action)); }}
fn fail(&self) {{ self.channel.fail_instance().map(|action| self.finish(action)); }}
fn force_sanitizer_failure() {{
    let _value = 1 + #[cfg(test)] 2;
}}
"#
    );
    assert!(
        runtime_filter_action_dispatch_boundary_violations(&unproven_body_dispatch)
            .iter()
            .any(|violation| violation.contains("bounded cfg analysis")),
        "an unproven finish body expression must fail the raw action fallback closed"
    );
    for bad in [
        good.replace("ChannelAction", "SubmitOutcome"),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "self.dispatcher.flush();",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "let action = crate::runtime_filter::core::channel::ChannelAction::None; self.dispatcher.dispatch(self.channel_id, action);",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "let _shadow = |action| action; self.dispatcher.dispatch(self.channel_id, action);",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "match action { action => self.dispatcher.dispatch(self.channel_id, action) }",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "let _dispatch = || { self.dispatcher.dispatch(self.channel_id, action); };",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "let _dispatch = async { self.dispatcher.dispatch(self.channel_id, action); };",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "if false { self.dispatcher.dispatch(self.channel_id, action); }",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "while false { self.dispatcher.dispatch(self.channel_id, action); }",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "return; self.dispatcher.dispatch(self.channel_id, action);",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "if true { return; } self.dispatcher.dispatch(self.channel_id, action);",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "let _: () = return; self.dispatcher.dispatch(self.channel_id, action);",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "let _: () = consume((if true { return; } else { () })); self.dispatcher.dispatch(self.channel_id, action);",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "let mut sink = (); sink = return; self.dispatcher.dispatch(self.channel_id, action);",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "if true {} else { self.dispatcher.dispatch(self.channel_id, action); }",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "for _ in [] { self.dispatcher.dispatch(self.channel_id, action); }",
        ),
        good.replace(
            "self.dispatcher.dispatch(self.channel_id, action);",
            "for _ in 0..0 { self.dispatcher.dispatch(self.channel_id, action); }",
        ),
        good.replace(
            "self.channel.submit().map(|action| self.finish(action))",
            "self.channel.submit().map(|action| action.outcome())",
        ),
        format!(
            "{good}\nfn bypass(&self, action: ChannelAction) {{ self.dispatcher.dispatch(self.channel_id, action); }}"
        ),
        good.replace("self.channel.submit()", "decoy.submit()"),
        good.replace(
            "self.channel.submit()",
            "RuntimeFilterChannel::submit(&self.channel)",
        ),
    ] {
        assert!(
            !runtime_filter_action_dispatch_boundary_violations(&bad).is_empty(),
            "dispatch detector must reject mutation-callback or action-free dispatch:\n{bad}"
        );
    }
}

#[test]
fn runtime_filter_root_dead_code_detector_rejects_attribute_bypasses() {
    for source in [
        "#![allow(dead_code)]\npub(crate) mod core; pub(crate) mod port; pub(crate) mod router; pub(crate) mod service;",
        "#[ allow ( dead_code ) ] pub(crate) mod core; pub(crate) mod port; pub(crate) mod router; pub(crate) mod service;",
        "#[allow(unused, dead_code)] pub(crate) mod core; pub(crate) mod port; pub(crate) mod router; pub(crate) mod service;",
        "#[cfg_attr(unix, allow(dead_code))] pub(crate) mod core; pub(crate) mod port; pub(crate) mod router; pub(crate) mod service;",
    ] {
        assert!(
            !runtime_filter_runtime_root_dead_code_violations(source).is_empty(),
            "dead-code detector must reject inner/spaced/combined attributes: {source}"
        );
    }
}

#[test]
fn runtime_filter_namespace_roots_reject_inner_dead_code_attributes() {
    for namespace in ["core", "materializer", "port", "router", "service"] {
        for source in [
            "#![allow(dead_code)]\npub(crate) mod child;",
            "#![ allow ( unused, dead_code ) ]\npub(crate) mod child;",
            "#![cfg_attr(unix, allow(dead_code))]\npub(crate) mod child;",
        ] {
            let source_rel = format!("src/runtime_filter/{namespace}/mod.rs");
            assert!(
                !runtime_filter_runtime_boundary_violations(&source_rel, source).is_empty(),
                "{source_rel} must reject inner dead_code suppression: {source}"
            );
        }
    }
}

#[test]
fn planner_logical_ir_and_payload_have_stage_owners() {
    let repo = Path::new(manifest_dir());
    let planner = repo.join("src/sql/planner");
    let logical_node_path = planner.join("logical/node.rs");
    let payload_path = planner.join("payload.rs");
    let physical_node_path = planner.join("physical/node.rs");
    let facade_path = planner.join("mod.rs");
    let logical_mod_path = planner.join("logical/mod.rs");
    let marker_path = planner.join("imv_rewrite/marker.rs");

    for path in [&logical_node_path, &payload_path, &physical_node_path] {
        assert!(path.is_file(), "missing planner IR owner: {}", rel(path));
    }
    assert!(
        !planner.join("plan.rs").exists(),
        "legacy physical IR owner src/sql/planner/plan.rs must be deleted"
    );

    let logical_only = [
        "LogicalPlanNode",
        "LogicalPlanKind",
        "LogicalApplyNode",
        "LogicalAggregateNode",
        "LogicalJoinNode",
        "LogicalUnionNode",
        "LogicalIntersectNode",
        "LogicalExceptNode",
        "LogicalImvDeltaNode",
        "LogicalImvVersionNode",
    ];
    let shared_payload = [
        "PlanScanNode",
        "PlanFilterNode",
        "PlanProjectNode",
        "PlanSortNode",
        "PlanLimitNode",
        "PlanValuesNode",
        "PlanRepeatNode",
        "PlanWindowNode",
        "PlanGenerateSeriesNode",
        "PlanTableFunctionNode",
        "PlanRowCountAssertion",
        "PlanAssertOneRowNode",
        "PlanCTEAnchorNode",
        "PlanCTEProduceNode",
        "PlanCTEConsumeNode",
        "WindowExpr",
        "AggregateCall",
    ];
    let physical_only = [
        "PhysicalTopNNode",
        "PhysicalHashAggregateNode",
        "PhysicalHashJoinNode",
        "PhysicalHashJoinEqCondition",
        "PhysicalNestLoopJoinNode",
        "PlanSetOpKind",
        "PhysicalSetOpNode",
        "DistributedChangeEventExpandNode",
        "DistributedChangeEventSpec",
        "DistributedChangeEventOutputExpr",
        "PhysicalPlanNode",
        "PhysicalPlanKind",
        "RedistributeNode",
        "RedistributeMode",
    ];
    let retired_logical_payload = [
        "LogicalAssertOneRowNode",
        "LogicalRepeatNode",
        "LogicalWindowNode",
        "LogicalGenerateSeriesNode",
        "LogicalTableFunctionNode",
        "LogicalScanNode",
        "LogicalValuesNode",
        "LogicalFilterNode",
        "LogicalProjectNode",
        "LogicalSortNode",
        "LogicalLimitNode",
        "LogicalCTEAnchorNode",
        "LogicalCTEProduceNode",
        "LogicalCTEConsumeNode",
    ];

    let planner_sources = rs_files(&planner)
        .into_iter()
        .map(|path| {
            let text = fs::read_to_string(&path).unwrap();
            (path, text)
        })
        .collect::<Vec<_>>();

    for (expected_owner, items) in [
        (&logical_node_path, logical_only.as_slice()),
        (&payload_path, shared_payload.as_slice()),
        (&physical_node_path, physical_only.as_slice()),
    ] {
        for item in items {
            let declarations = planner_sources
                .iter()
                .filter_map(|(path, text)| {
                    let count = rust_named_type_declaration_count(text, item);
                    (count > 0).then(|| format!("{} ({count})", rel(path)))
                })
                .collect::<Vec<_>>();
            assert_eq!(
                declarations,
                vec![format!("{} (1)", rel(expected_owner))],
                "{item} must have exactly one declaration in its stage owner"
            );
        }
    }

    for item in retired_logical_payload {
        let declarations = planner_sources
            .iter()
            .filter_map(|(path, text)| {
                let count = rust_named_type_declaration_count(text, item);
                (count > 0).then(|| format!("{} ({count})", rel(path)))
            })
            .collect::<Vec<_>>();
        assert!(
            declarations.is_empty(),
            "retired logical payload {item} must not be declared: {declarations:?}"
        );
    }

    let plan = fs::read_to_string(&physical_node_path).unwrap();
    let plan_production = rust_sanitized_production_text(&plan);
    let plan_identifiers = plan_production
        .split(|ch: char| !is_ident_char(ch))
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>();
    assert!(
        !plan_identifiers
            .iter()
            .any(|token| token.starts_with("Logical")),
        "physical staging owner must not reference Logical* production types"
    );
    let plan_uses = rust_production_use_statements(&plan);
    assert!(
        !plan_uses.iter().any(|import| {
            rust_use_imports_stage(import, "logical")
                || (rust_use_is_public(import)
                    && (rust_use_imports_stage(import, "payload")
                        || rust_use_imports_sql_common(import)))
        }),
        "physical/node.rs must not import logical IR or re-export shared/common payload; the boundary guard conservatively expands aliases across lexical scopes and may restrict legal same-name reuse to avoid false negatives: {plan_uses:?}"
    );

    let payload = fs::read_to_string(&payload_path).unwrap();
    let payload_uses = rust_production_use_statements(&payload);
    assert!(
        !payload_uses.iter().any(|import| {
            ["logical", "plan", "distributed"]
                .into_iter()
                .any(|stage| rust_use_imports_stage(import, stage))
        }),
        "payload.rs must not import stage owners: {payload_uses:?}"
    );
    let payload_production = compact_line(&rust_sanitized_production_text(&payload));
    for forbidden in ["planner::logical", "planner::plan", "planner::distributed"] {
        assert!(
            !payload_production.contains(forbidden),
            "payload.rs must not depend on stage owner {forbidden}"
        );
    }

    let logical_node = fs::read_to_string(&logical_node_path).unwrap();
    let logical_production = rust_sanitized_production_text(&logical_node);
    let logical_identifiers = logical_production
        .split(|ch: char| !is_ident_char(ch))
        .filter(|token| !token.is_empty())
        .collect::<Vec<_>>();
    assert!(
        !logical_identifiers.iter().any(|token| {
            token.starts_with("Physical")
                || token.starts_with("Redistribute")
                || *token == "distributed"
                || *token == "PlanSetOpKind"
        }),
        "logical/node.rs production must not depend on physical/distributed owners"
    );
    let logical_uses = rust_production_use_statements(&logical_node);
    assert!(
        !logical_uses.iter().any(|import| {
            ["plan", "physical", "distributed"]
                .into_iter()
                .any(|stage| rust_use_imports_stage(import, stage))
        }),
        "logical/node.rs production must not import physical/distributed owners: {logical_uses:?}"
    );

    let facade = fs::read_to_string(&facade_path).unwrap();
    assert!(has_non_comment_line(&facade, "pub(crate) mod payload;"));
    let facade_uses = rust_production_use_statements(&facade);
    let actual_ir_surface = facade_uses
        .iter()
        .filter(|import| {
            ["logical", "payload", "physical"]
                .into_iter()
                .any(|stage| rust_use_imports_stage(import, stage))
        })
        .cloned()
        .collect::<BTreeSet<_>>();
    let expected_ir_surface = BTreeSet::from([
        "pub(crate)|logical::build::plan_output_columns".to_string(),
        "pub(crate)|logical::build::plan_query".to_string(),
    ]);
    assert_eq!(
        actual_ir_surface, expected_ir_surface,
        "planner facade must not hide logical/shared IR owners: {facade_uses:?}"
    );

    let logical_mod = fs::read_to_string(&logical_mod_path).unwrap();
    assert!(has_non_comment_line(&logical_mod, "mod node;"));
    let logical_mod_uses = rust_production_use_statements(&logical_mod);
    assert_eq!(
        logical_mod_uses,
        vec!["pub(crate)|node::*"],
        "logical module use surface must only re-export node::*"
    );

    let marker = fs::read_to_string(&marker_path).unwrap();
    let marker_uses = rust_production_use_statements(&marker);
    assert!(
        !marker_uses.iter().any(|import| {
            rust_use_is_public(import) && rust_use_leaf(import) == "ImvVersionRef"
        }),
        "imv_rewrite::marker must not re-export ImvVersionRef: {marker_uses:?}"
    );

    let mut checked = rs_files(&src_dir());
    checked.extend(rs_files(&repo.join("tests")));
    let legacy_logical_path = ["planner::plan::", "Logical"].concat();
    for path in checked {
        let text = fs::read_to_string(&path).unwrap();
        let sanitized = rust_lexically_sanitized(&text);
        let imports = rust_production_use_statements(&text);
        assert!(
            !sanitized.contains(&legacy_logical_path),
            "legacy logical path remains in {}",
            rel(&path)
        );
        for import in &imports {
            if !rust_use_imports_stage(import, "plan") {
                continue;
            }
            let leaf = rust_use_leaf(import);
            assert_ne!(
                leaf,
                "*",
                "legacy planner::plan wildcard import remains after conservative cross-scope alias expansion in {}: {import}",
                rel(&path)
            );
            assert!(
                !leaf.starts_with("Logical"),
                "legacy logical import remains in {}: {import}",
                rel(&path)
            );
        }
        for item in shared_payload {
            assert!(
                !sanitized.contains(&format!("planner::plan::{item}")),
                "legacy shared payload path planner::plan::{item} remains in {}",
                rel(&path)
            );
            assert!(
                !imports.iter().any(|import| {
                    rust_use_imports_stage(import, "plan") && rust_use_leaf(import) == item
                }),
                "legacy shared payload import planner::plan::{item} remains in {}",
                rel(&path)
            );
        }
    }
}

