        production_rs_files_from_entries(&src, &[src.join("lib.rs"), src.join("main.rs")])
            .into_iter()
            .map(|path| Cgo8GuardSource::new(rel(&path), fs::read_to_string(path).unwrap()))
            .collect::<Vec<_>>();
    let violations = cgo_9a_task2_violations(&sources);
